function enrich(c:Case,index:number):Case {
 const chapter=index<3?1:index<6?2:3;
 const speaker=index%2===0?{name:'Алина',role:'Руководитель продукта'}:{name:'Марк',role:'Продуктовый аналитик'};
 const defaults:Partial<Case>={variant:0,chapter,skills:skillNames,briefing:{...speaker,message:`Нужен обоснованный план для ${c.company}. Не спешите с запуском: покажите, что изменилось, как проверить идею и какие риски мы принимаем.`},hints:defaultHints,sourceIds:['sommerville','nist','statsmodels'],illustration:index%3===0?'/images/mission-market.svg':index%3===1?'/images/mission-growth.svg':'/images/mission-experiment.svg',srm:'ok',guardrailStatus:'ok',economicsUncertain:c.id==='food',consequences:[
  c.decision===0?'Учебное последствие: команда начинает поэтапный rollout и сохраняет мониторинг. Решение согласовано с планом; величина будущего эффекта не гарантирована.':'Учебное последствие: преждевременный rollout переносит непроверенный эффект или обнаруженный риск на всю аудиторию. Данных для такого масштаба решения недостаточно.',
  c.decision===1?'Учебное последствие: команда сохраняет контроль и готовит отдельное исследование или исправление. Это ограничивает риск, но не является реальным наблюдением.':'Учебное последствие: команда сохраняет текущую версию. Риск ограничен, но возможность улучшения или выполнение исходного плана отложены.',
  c.decision===2?'Учебное последствие: сбор продолжается до исходной плановой границы без изменения критерия. Статистическая значимость всё ещё не гарантирована.':'Учебное последствие: незапланированное продление не устраняет дефект дизайна и может увеличить риск ложного вывода. Нужен отдельный план.',
  c.decision===3?'Учебное последствие: команда запускает пилот на части пользователей с заранее заданной метрикой и условием отката. Риск ограничен, а неопределённость денежного эффекта будет оценена на реальных данных.':c.decision===0?'Учебное последствие: пилот ограничивает риск, но откладывает пользу уже подтверждённого изменения. Без критерия расширения он может затянуться.':'Учебное последствие: пилот переносит неподтверждённый эффект или обнаруженный риск на часть реальных пользователей. Основания для этого шага в данных нет.'
 ]};
 const merged={...defaults,...c};
 return {...merged,takeaways:buildTakeaways(merged)};
}
const fmtP=(p:number|null)=>p===null?'не рассчитан':p<.001?'< 0,001':`≈ ${p.toLocaleString('ru-RU',{maximumFractionDigits:3})}`;
const n=(v:number)=>v.toLocaleString('ru-RU');
/**
 * Таблица «Что наблюдали / Что можем утверждать / Чего это не доказывает».
 * Строки 2–3 считаются из данных варианта, поэтому всегда соответствуют цифрам.
 */
export function buildTakeaways(c:Case):{observed:string;claim:string;limit:string}[]{
 const nB=c.nB??c.n;const s=compareProportions(c.xA,c.n,c.xB,nB);const srm=c.srm==='failed'||sampleRatioMismatch(c.n,nB).mismatch;
 const sig=s.pValue!==null&&s.pValue<.05;const reached=c.n>=c.planned&&nB>=c.planned;
 const rows=[c.insight||{observed:c.diagnosticExplanation,claim:'Декомпозиция локализует изменившийся компонент.',limit:'Причинный механизм поведения.'}];
 const effect=`${c.primary[0]}: ${percent(s.a,1)} в A и ${percent(s.b,1)} в B (${points(s.delta)}), p ${fmtP(s.pValue)}.`;
 rows.push(srm?{observed:effect,claim:'Наблюдаемая разница может быть следствием поломки распределения, а не изменения.',limit:'Любой причинный вывод об эффекте.'}
  :!sig?{observed:effect,claim:'Есть сдвиг в выборке, но на уровне α = 0,05 он не подтверждён.',limit:'Что эффект реален: интервал включает ноль.'}
  :s.delta>0?{observed:effect,claim:'Изменение связано с ростом основной метрики в тесте.',limit:'Что эффект сохранится в других сегментах и через полгода.'}
  :{observed:effect,claim:c.economicsUncertain?'Новое условие отпугивает часть пользователей.':'Вариант B ухудшает основную метрику.',limit:c.economicsUncertain?'Что итог для бизнеса отрицательный.':'Что плох каждый элемент варианта B — механизм нужно разобрать.'});
 if(srm)rows.push({observed:`Группы разного размера: A — ${n(c.n)}, B — ${n(nB)} при плане 50/50.`,claim:'Распределение трафика сломано (SRM).',limit:'Любой вывод об эффекте: тест нужно чинить и перезапускать.'});
 else if(!reached)rows.push({observed:`Выборка ${n(Math.min(c.n,nB))} из ${n(c.planned)} по плану.`,claim:'Тест не завершён.',limit:'Что эффекта нет: мощности пока не хватает.'});
 else if(c.economicsUncertain&&c.economics){const a=s.a*c.economics.marginA,b=s.b*c.economics.marginB;rows.push({observed:`Маржинальная прибыль на пользователя выше на ${percent(b/a-1,1)} по точечной оценке (${n(+a.toFixed(2))} → ${n(+b.toFixed(2))} ₽).`,claim:'Каждый оставшийся покупатель выгоднее.',limit:'Точный денежный эффект: нет поюзерных данных о прибыли.'});}
 else if(c.guardrailStatus==='failed')rows.push({observed:`Контрольная метрика ухудшилась: ${c.guardrails[0].toLowerCase()}.`,claim:'Есть вред, который перевешивает пользу основной метрики.',limit:'Что раскатывать безопасно.'});
 else rows.push({observed:`План выполнен: ${n(Math.min(c.n,nB))} из ${n(c.planned)} на группу, SRM нет, контрольные метрики в норме.`,claim:'Тесту можно доверять в рамках его дизайна.',limit:sig?'Что эффект перенесётся на другие аудитории без проверки.':'Что эффекта нет: незначимость не доказывает равенство.'});
 return rows;
}
originalCases[0].checks=[derived('revenue','multiply','orders','basket'),derived('orders','multiply','visitors','conversion')];
originalCases[1].checks=[derived('end','balance','start','new','cancel')];
originalCases[2].checks=[derived('margin','subtract','income','cost'),derived('profit','multiply','orders','margin')];
originalCases[2].guardrailStatus='unknown';
export const cases:Case[]=[...originalCases,...newCases].map(enrich);
