export function caseVariants(id:string):Case[]{const base=cases.find(c=>c.id===id);if(!base)return [];return [base,...(alternatives[id]||[]).map((changes,i)=>{const {consequences:_consequences,takeaways:_takeaways,...variantBase}=base;return enrich({...variantBase,...changes,why:{...base.why,...changes.why},variant:i+1},cases.indexOf(base));})];}
export function getCase(id:string,variantIndex=0):Case {const variants=caseVariants(id);if(!variants.length)throw new Error('Учебный кейс не найден');return variants[((variantIndex%variants.length)+variants.length)%variants.length];}
